```rust
wit_bindgen::generate!({
    path: "wit",
    world: "node",
    generate_all,
});

use crate::aap::caps::response_channel;

struct Node;

impl Guest for Node {
    fn run(reply: AgentResponse) -> DeliveryConfirmation {
        // The channel stamps its own session identity on the confirmation;
        // the node never fabricates it.
        let confirmation = response_channel::send(&reply.text);

        // The contract requires `delivered == true` and a present session on
        // every output. If the host did not accept the message, there is no
        // honest output to produce: trap rather than forge a confirmation or
        // re-send (which could deliver twice).
        if !confirmation.delivered || confirmation.session.is_empty() {
            panic!("response channel did not confirm delivery");
        }

        confirmation
    }
}

export!(Node);
